"""Pydantic schemas for conversational workflow synthesis (Milestone P11.1)."""

from typing import Any, Literal
from pydantic import BaseModel, ConfigDict, Field

from pico.schemas.workflow import WorkflowCreate


class SynthesizedStepModel(BaseModel):
    """Specification of an individual step generated by the model."""
    step_key: str = Field(
        ...,
        min_length=1,
        max_length=128,
        pattern=r"^[a-zA-Z0-9_\-]+$",
        description="Unique identifier for the step within this workflow",
    )
    capability_id: str = Field(
        ...,
        min_length=1,
        max_length=128,
        description="Registered capability identifier to execute",
    )
    capability_version: str = Field(
        default="1.0.0",
        max_length=32,
        description="Expected capability version",
    )
    dependencies: list[str] = Field(
        default_factory=list,
        description="List of step_keys that must successfully complete before this step can run",
    )
    input_template: dict[str, Any] = Field(
        default_factory=dict,
        description="Input parameters or dependency output mappings for the capability",
    )
    explanation: str | None = Field(
        default=None,
        max_length=512,
        description="Brief justification for why this step was selected",
    )

    model_config = ConfigDict(extra="forbid")


class WorkflowSynthesisPlan(BaseModel):
    """Strict structured model output contract for workflow synthesis."""
    status: Literal["ready", "needs_clarification", "unsupported"] = Field(
        ...,
        description="Outcome state of the synthesis attempt",
    )
    workflow_name: str | None = Field(
        default=None,
        max_length=255,
        description="Human-readable name for the synthesized workflow plan",
    )
    workflow_description: str | None = Field(
        default=None,
        max_length=1000,
        description="Summary of what the workflow achieves",
    )
    steps: list[SynthesizedStepModel] = Field(
        default_factory=list,
        description="Ordered or DAG steps composing the plan (empty if needs_clarification or unsupported)",
    )
    explanation: str | None = Field(
        default=None,
        max_length=1000,
        description="User-facing summary explaining the workflow or refusal reason",
    )
    clarification_question: str | None = Field(
        default=None,
        max_length=500,
        description="Clarification question when user request is ambiguous or lacks required parameters",
    )

    model_config = ConfigDict(extra="forbid")


class WorkflowSynthesizeRequest(BaseModel):
    """Request payload to synthesize a workflow DAG from a conversation user message."""
    conversation_id: str = Field(
        ...,
        min_length=1,
        max_length=64,
        description="Target conversation ID",
    )
    user_message_id: str = Field(
        ...,
        min_length=1,
        max_length=64,
        description="Persisted user message ID to convert into a workflow proposal",
    )
    requested_profile: str | None = Field(
        default=None,
        description="Optional preferred profile (subject to routing policy and benchmark gate)",
    )

    model_config = ConfigDict(extra="forbid")


class SynthesizedStepDetail(BaseModel):
    """Server-derived step information including authoritative risk and authorization attributes."""
    step_key: str
    capability_id: str
    capability_version: str
    capability_name: str
    capability_description: str
    dependencies: list[str]
    input_template: dict[str, Any]
    risk_tier: str
    required_permission: str | None = None
    consequential: bool
    requires_approval: bool
    explanation: str | None = None

    model_config = ConfigDict(extra="forbid")


class WorkflowSynthesizeResponse(BaseModel):
    """Proposal-only response returned to the user for explicit review."""
    status: Literal["ready", "needs_clarification", "unsupported"]
    conversation_id: str
    user_message_id: str
    workflow_proposal: WorkflowCreate | None = None
    step_details: list[SynthesizedStepDetail] = Field(default_factory=list)
    explanation: str | None = None
    clarification_question: str | None = None
    effective_classification: str
    selected_profile: str
    provider: str
    model_name: str

    model_config = ConfigDict(extra="forbid")
